document.addEventListener('DOMContentLoaded', async () => {
    const mapContainer = document.getElementById('global-travel-map');
    if (!mapContainer) return; // Exit if we aren't on the travel map page

    try {
        // 1. Fetch the locations data generated by our worker
        const response = await fetch('/assets/locations.json');
        if (!response.ok) throw new Error('Failed to load locations data');
        
        const locations = await response.json();
        
        if (locations.length === 0) {
            mapContainer.innerHTML = '<p style="text-align:center; padding:2rem;">No travel locations found yet!</p>';
            return;
        }

        // 2. Initialize the Leaflet map
        // We start at [20, 0] (middle of the world) and zoom level 2. 
        // We will auto-zoom later once we know where the markers are.
        const map = L.map('global-travel-map').setView([20, 0], 2);
        
        // Add the standard OpenStreetMap tiles
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; OpenStreetMap contributors',
            maxZoom: 19
        }).addTo(map);

        // 3. Initialize the MarkerCluster Group (Task 5.7)
        // This automatically groups markers that are close together when zoomed out
        const markers = L.markerClusterGroup({
            maxClusterRadius: 50, // Pixels radius to cluster
            spiderfyOnMaxZoom: true, // If zoomed in all the way and they still overlap, create a "spider web"
            showCoverageOnHover: false,
        });

        // 4. Loop through all locations and create markers (Tasks 5.4 & 5.5)
        locations.forEach(loc => {
            // Create a standard Leaflet marker
            const marker = L.marker([loc.location.lat, loc.location.lng]);
            
            // Build the custom popup HTML (Task 5.5)
            let popupContent = `<div class="wanderghost-popup">`;
            
            // Add featured image if it exists
            if (loc.featureImage) {
                popupContent += `<img src="${loc.featureImage}" alt="${loc.postTitle}">`;
            }
            
            // Add title and link
            popupContent += `
                <h3>${loc.postTitle}</h3>
                <p style="margin:0 0 8px 0; color:#666; font-size:13px;">${loc.location.label}</p>
                <a href="${loc.postUrl}">Read the story →</a>
            </div>`;
            
            // Bind the popup to the marker
            marker.bindPopup(popupContent, { maxWidth: 250 });
            
            // Add the marker to the cluster group
            markers.addLayer(marker);
        });

        // 5. Add the cluster group to the map
        map.addLayer(markers);

        // 6. Auto-Zoom to fit all markers (Task 5.6)
        // This calculates the bounding box of all markers and zooms the map to fit them perfectly
        if (locations.length > 1) {
            map.fitBounds(markers.getBounds(), { padding: [50, 50] });
        } else if (locations.length === 1) {
            // If there's only one post, just zoom in on it
            map.setView([locations[0].location.lat, locations[0].location.lng], 10);
        }

    } catch (error) {
        console.error('WanderGhost Global Map Error:', error);
        mapContainer.innerHTML = '<p style="text-align:center; color:red; padding:2rem;">Error loading travel map.</p>';
    }
});